\documentclass{article}
\usepackage[T1]{fontenc}
\usepackage[utf8]{inputenc}
\usepackage[spanish]{babel}
\usepackage{amssymb}
\usepackage{amsmath}
\usepackage{amsthm}
\newtheorem{definicion}{Definición}
\newtheorem{teorema}{Teorema}
\title{Cuaderno matemático}
\author{Estudiante}
\date{\today}

\begin{document}
\maketitle

\begin{definicion}Un racional es un número $x$ para el cual $\exists p,q\in\mathbb{Z}$ con $q\neq0$ y $x=\frac{p}{q}$.\end{definicion}
\begin{teorema}Todo entero es racional.\end{teorema}
\begin{proof}Para $n\in\mathbb{Z}$, se tiene $n=\frac{n}{1}$.\end{proof}
\end{document}
